export function getAllBlogs() {
  return blogs.filter(blog => blog.published);
}

export function getBlogBySlug(slug) {
  return blogs.find(blog => blog.slug === slug && blog.published);
}

export function getBlogsByCategory(category) {
  if (!category) return [];
  if (category.toLowerCase() === 'all') return getAllBlogs();
  const normalized = category.toLowerCase();
  return blogs.filter(blog => blog.published && (blog.category || '').toLowerCase() === normalized);
}

export function getBlogsByDestination(destination, limit = 10) {
  return blogs.filter(blog => blog.published && blog.destination && blog.destination.toLowerCase() === destination.toLowerCase()).slice(0, limit);
}

export function getLatestBlogs(limit = 6) {
  return blogs.filter(blog => blog.published).sort((a, b) => new Date(b.publishDate) - new Date(a.publishDate)).slice(0, limit);
}

export function getRelatedBlogs(currentSlug, category, limit = 3) {
  return blogs.filter(blog => blog.published && blog.slug !== currentSlug && blog.category === category).slice(0, limit);
}